                .split(',')
                .map(|part| part.trim().parse::<usize>())
                .collect::<Result<_, _>>()
                .map_err(|_| anyhow::anyhow!("--seats must be comma-separated integers"))?;
            harness_cmd::run(harness_cmd::Args {
                seats,
                seed_base,
                games_per_seat,
