            file,
            verbose,
            branch_at,
            branch_out,
            compare_with,
            save_out,
        } => replay_cmd::run(
            &file,
            verbose,
            branch_at,
            branch_out,
            compare_with,
            save_out,
        ),
        Command::Import {
            url,
            cache,
            out,
            plan,
            json,
        } => import_cmd::import_url(&url, &cache, out.as_deref(), plan, json),
        Command::ImportTxt { file, name, json } => {
            import_cmd::import_text(&file, name.as_deref(), json)
        }
        Command::Pool => info_cmd::pool(),
        Command::Decks => info_cmd::decks(),
        Command::Coach {
            seed,
