//! THE APERTURE headless CLI: offline self-play, replay verification, coaching
//! output, and real (bounded) Archidekt import.

mod commander_cmd;
mod decks;
mod harness_cmd;
mod import_cmd;
mod info_cmd;
mod replay_cmd;
mod selfplay_cmd;

use std::path::PathBuf;

use clap::{Parser, Subcommand};

#[derive(Parser, Debug)]
#[command(
    name = "aperture-cli",
    version,
    about = "THE APERTURE — practice slice CLI (supported card pool, 1v1, 20 life, NOT Commander)"
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

#[derive(Subcommand, Debug)]
pub enum Command {
    /// Play one deterministic 2-4 seat AI game and report the result.
    Selfplay {
        #[arg(long, default_value_t = 1)]
        seed: u64,
        /// Seat count when no explicit --deck paths are supplied (2..=4).
        #[arg(long)]
        seats: Option<usize>,
        /// One deck path per seat; repeat 2..=4 times. Defaults to the bundled
        /// practice decks (cycling A/B for extra seats).
        #[arg(long = "deck")]
        deck: Vec<PathBuf>,
        #[arg(long, default_value_t = 4000)]
        max_steps: usize,
        /// Wall-clock bound for the run, milliseconds.
        #[arg(long)]
        max_millis: Option<u64>,
        /// Use the local Decider-2B service for this seat (0..=3).
        #[arg(long)]
        decider_seat: Option<u8>,
        #[arg(long, default_value_t = 4000)]
        decider_timeout_ms: u64,
        /// Write the machine-readable report here.
        #[arg(long)]
        out: Option<PathBuf>,
        /// Also write the replay (with digest) here.
        #[arg(long)]
        replay_out: Option<PathBuf>,
        /// Print every event.
        #[arg(long)]
        verbose: bool,
        /// Explicit command-zone practice profile (20 life, one supported
        /// commander per seat, NOT full Commander).
        #[arg(long = "command-zone-practice")]
        command_zone_practice: bool,
        /// Explicit BOUNDED Commander-combat practice profile (40 life, one
        /// supported commander per seat, NOT the Commander format).
        #[arg(long = "commander-combat-practice")]
        commander_combat_practice: bool,
        /// One `SEAT:CARD` commander spec per seat; requires an explicit
        /// command-zone profile (`--command-zone-practice` or
        /// `--commander-combat-practice`). Example:
        /// `0:Jasmine Boreal`. Supported commanders: Isamaru, Hound of Konda;
        /// Jasmine Boreal.
        #[arg(long = "commander")]
        commander: Vec<String>,
    },
    /// Run bounded 2/3/4-seat headless games with paired seeds and verify every
    /// replay digest. Exit 0 all terminal, 2 capped but no failure, 1 failure.
    Harness {
        /// Comma-separated seat counts (default 2,3,4).
        #[arg(long, default_value = "2,3,4")]
        seats: String,
        #[arg(long, default_value_t = 1)]
        seed_base: u64,
        #[arg(long, default_value_t = 4)]
        games_per_seat: usize,
        #[arg(long, default_value_t = 4000)]
        max_steps: usize,
        #[arg(long)]
        max_millis: Option<u64>,
        #[arg(long, default_value = "evidence/m1-harness.json")]
        out: PathBuf,
    },
    /// Verify a save file or replay file: re-run it and compare digests.
    Replay {
        #[arg(long)]
        file: PathBuf,
        #[arg(long)]
        verbose: bool,
        /// Cut a branch at this recorded action index and verify the branched
        /// line replays deterministically. `branch_out` writes the branch.
        #[arg(long)]
        branch_at: Option<usize>,
        /// Write the cut branch line here (a replay file, replay version 6).
        #[arg(long)]
        branch_out: Option<PathBuf>,
        /// Compare the file's recorded line against this second line (same
        /// setup) and print the public accepted-action differences only.
        #[arg(long)]
        compare_with: Option<PathBuf>,
        /// For a bare replay file: verify it and write a certified session
        /// save of the replayed final state here (used to deliver a finished
        /// game into the native table).
        #[arg(long)]
        save_out: Option<PathBuf>,
    },
    /// Import a public Archidekt deck by URL (allowlisted host only).
    Import {
        #[arg(long)]
        url: String,
        #[arg(long, default_value = "cache")]
        cache: PathBuf,
        #[arg(long)]
        out: Option<PathBuf>,
        /// Attempt to plan the deck for play (refuses unsupported cards).
        #[arg(long)]
        plan: bool,
        /// Print the report JSON.
        #[arg(long)]
        json: bool,
    },
    /// Import a text deck list (the offline fallback).
    ImportTxt {
        #[arg(long)]
        file: PathBuf,
        #[arg(long)]
        name: Option<String>,
        #[arg(long)]
        json: bool,
    },
    /// Show the supported card pool.
    Pool,
    /// Show the bundled practice decks.
    Decks,
    /// Print the coaching explanation for the opening decision of a game.
    Coach {
        #[arg(long, default_value_t = 1)]
        seed: u64,
        #[arg(long)]
        deck_a: Option<PathBuf>,
        #[arg(long)]
        deck_b: Option<PathBuf>,
    },
    /// Analyze an offline Commander deck snapshot. Format legality only; never
    /// starts a game. Exit 0 legal, 1 illegal, 2 not_certified/input error.
    CommanderCheck {
        #[arg(long)]
        deck: PathBuf,
        #[arg(long)]
        cards: PathBuf,
        /// Print the versioned report JSON.
        #[arg(long)]
        json: bool,
        /// Write the report JSON here (same bytes as --json stdout).
        #[arg(long)]
        out: Option<PathBuf>,
    },
    /// Check whether the optional local Decider-2B service is reachable.
    DeciderHealth {
        #[arg(long, default_value = "http://127.0.0.1:8765")]
        base_url: String,
    },
}

