#[test]
fn signets_cast_from_hand_and_identity_survives_commander_leaving_command_zone() {
    let deck = DeckList::parse_practice("x", "40 Mountain\n").unwrap();
    let mut game = Game::new_commander_combat(
        185,
        &[deck.clone(), deck],
        &[(P0, card("Krenko, Mob Boss")), (P1, card("Krenko, Mob Boss"))],
    )
    .unwrap();
    game.state.mulligan = None;
    game.state.pending = None;
    game.state.turn.active = P0;
    game.state.turn.step = Step::PrecombatMain;
    game.state.turn.priority = Some(P0);
    for _ in 0..3 {
        let id = ObjectId(game.state.next_object);
        game.state.next_object += 1;
        game.state.objects.insert(id, aperture_core::state::Object {
            id, card: CardId::Mountain, owner: P0, controller: P0, zone: Zone::Battlefield,
            commander: None, tapped: false, damage: 0, summoning_sick: false,
            pump_power: 0, pump_toughness: 0, plus_one_counters: 0, counters: Default::default(),
        });
    }
    let hand_id = {
        let id = ObjectId(game.state.next_object); game.state.next_object += 1;
        game.state.objects.insert(id, aperture_core::state::Object {
            id, card: card("Arcane Signet"), owner: P0, controller: P0, zone: Zone::Hand,
            commander: None, tapped: false, damage: 0, summoning_sick: false,
            pump_power: 0, pump_toughness: 0, plus_one_counters: 0, counters: Default::default(),
        });
        game.state.players[P0 as usize].hand.push(id); id
    };
    submit_ok(&mut game, P0, Action::CastSpell { card: hand_id, targets: Vec::new() });
    for _ in 0..4 { if game.state.stack.is_empty() { break; } let p=game.decision_owner().unwrap(); submit_ok(&mut game,p,Action::Pass); }
    let signet = game.state.battlefield(P0).into_iter().find(|o| o.card==card("Arcane Signet")).unwrap().id;
    assert_eq!(offered_colors(&game, signet), vec![ManaColor::Red]);
    // Move the commander out of the command zone; registered identity remains.
    let commander = game.state.player(P0).command_zone[0];
    game.state.players[P0 as usize].command_zone.retain(|id| *id != commander);
    game.state.objects.get_mut(&commander).unwrap().zone = Zone::Graveyard;
    assert_eq!(offered_colors(&game, signet), vec![ManaColor::Red]);
}

