        aperture_core::Action::AnswerCommanderDraw {
            to_command_zone: true,
        },
    )
    .expect("accept");
    let command = game.state.commanders[0].object;
    assert_ne!(command, top);
    assert_eq!(
        game.state.object(command).zone,
